/* Generated by FFmpeg's configure at build time; hand-written here for arm64-v8a / armeabi-v7a
 * (both little-endian, both allow fast unaligned access). Neither macro changes struct layouts. */
#ifndef AVUTIL_AVCONFIG_H
#define AVUTIL_AVCONFIG_H
#define AV_HAVE_BIGENDIAN 0
#define AV_HAVE_FAST_UNALIGNED 1
#endif /* AVUTIL_AVCONFIG_H */
